(function(){
  var SUPABASE_URL = '';
  var SUPABASE_ANON_KEY = 'local';
  fetch(SUPABASE_URL + '/rest/v1/map_settings?id=eq.1&select=gtm_container_id,search_console_verification', {
    headers: { 'apikey': SUPABASE_ANON_KEY, 'Authorization': 'Bearer ' + SUPABASE_ANON_KEY }
  }).then(function(r){ return r.json(); }).then(function(rows){
    var row = rows && rows[0];
    if(!row) return;
    if(row.search_console_verification){
      var meta = document.createElement('meta');
      meta.name = 'google-site-verification';
      meta.content = row.search_console_verification;
      document.head.appendChild(meta);
    }
    if(row.gtm_container_id){
      window.dataLayer = window.dataLayer || [];
      window.dataLayer.push({ 'gtm.start': new Date().getTime(), event: 'gtm.js' });
      var j = document.createElement('script');
      j.async = true;
      j.src = 'https://www.googletagmanager.com/gtm.js?id=' + row.gtm_container_id;
      document.head.appendChild(j);
      document.addEventListener('DOMContentLoaded', function(){
        var ifr = document.createElement('iframe');
        ifr.src = 'https://www.googletagmanager.com/ns.html?id=' + row.gtm_container_id;
        ifr.height = 0; ifr.width = 0; ifr.style.display = 'none'; ifr.style.visibility = 'hidden';
        var ns = document.createElement('noscript');
        ns.appendChild(ifr);
        document.body.insertBefore(ns, document.body.firstChild);
      });
    }
  }).catch(function(){});
})();

(function(){
  var ALLOWED_HOSTS = []; // e.g. ['associatte.com','www.associatte.com']
  if(ALLOWED_HOSTS.length && ALLOWED_HOSTS.indexOf(location.hostname) === -1){
    document.write('<div style="display:flex;align-items:center;justify-content:center;height:100vh;font-family:sans-serif;text-align:center;padding:20px;color:#4a5568;">This map is licensed for use on its original website only.</div>');
    window.stop ? window.stop() : (document.execCommand && document.execCommand('Stop'));
  }
})();

(async function(){

  const SUPABASE_URL = '';
  const SUPABASE_ANON_KEY = 'local';
  const sb = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

  const statusColor = {available:'#3f8f6b', sold:'#b5484c', construction:'#c98a2c', upcoming:'#3b6ea5'};
  const statusLabel = {available:'Available', sold:'Sold', construction:'Under Construction', upcoming:'Upcoming'};

  const infraTypes = {
    bridge:          {emoji:'🌉', label:'Bridge',              color:'#3b6ea5'},
    highway_bridge:  {emoji:'🛣️', label:'Highway Bridge',       color:'#8f6f42'},
    flyover:         {emoji:'🎢', label:'Flyover',              color:'#7a5c9e'},
    bullet_train:    {emoji:'🚄', label:'Bullet Train Station', color:'#b5484c'},
    metro:           {emoji:'🚇', label:'Metro Station',        color:'#3f8f6b'},
    railway_station: {emoji:'🚉', label:'Railway Station',      color:'#5b7c99'},
    hotel:           {emoji:'🏨', label:'Hotel',                color:'#a0527a'},
    hospital:        {emoji:'🏥', label:'Hospital',             color:'#c0392b'},
    underpass:       {emoji:'🔽', label:'Underpass',            color:'#5c6670'},
    proposed_road:   {emoji:'🚧', label:'Proposed Road',        color:'#c98a2c'},
    school:          {emoji:'🏫', label:'School',                color:'#5c8a3f'}
  };
  const infraSizes = {small:{px:26, font:13}, medium:{px:36, font:18}, large:{px:48, font:24}};
  function isBridgeLike(type){ return type === 'bridge' || type === 'highway_bridge' || type === 'flyover'; }

  function pinShareUrl(pin){
    const url = new URL(window.location.href);
    url.search = '';
    url.searchParams.set('pin', pin.id);
    return url.toString();
  }
  async function sharePin(pin){
    const url = pinShareUrl(pin);
    const shareData = {
      title: pin.title || 'Land parcel — Associatte',
      text: 'Check out this land parcel on the Associatte Interactive Map: ' + (pin.title || ''),
      url
    };
    if(navigator.share){
      try{ await navigator.share(shareData); return; }
      catch(_e){ /* user cancelled or share failed — fall through to copy */ }
    }
    try{
      await navigator.clipboard.writeText(url);
      alert('Link copied — you can now paste and share it.');
    }catch(_e){
      window.prompt('Copy this link to share:', url);
    }
  }
  window.sharePin = sharePin;

  function teaserLine(p){
    if(p.status === 'construction'){
      const bits = [p.configuration, p.sqft].filter(Boolean).join(' · ');
      const poss = p.possession_timeline ? ('Possession: ' + p.possession_timeline) : '';
      return [bits, poss].filter(Boolean).join('<br>') || 'Details on request';
    }
    if(p.status === 'upcoming'){
      const bits = [p.configuration, p.sqft].filter(Boolean).join(' · ');
      const launch = p.launch_date ? ('Launching: ' + p.launch_date) : '';
      return [bits, launch].filter(Boolean).join('<br>') || 'Launching soon';
    }
    if(p.status === 'available'){
      return p.whats_available || (p.price || 'Enquire for availability');
    }
    return 'This project has been sold out.';
  }

  /* ---------------------------------------------------------
     LOAD DATA
  --------------------------------------------------------- */
  const [pinsRes, infraRes, roadsRes, settingsRes] = await Promise.all([
    sb.from('pins').select('*'),
    sb.from('infra_markers').select('*'),
    sb.from('roads').select('*'),
    sb.from('map_settings').select('*').eq('id', 1).single()
  ]);
  const pins = pinsRes.data || [];
  const bridges = infraRes.data || [];
  const roads = roadsRes.data || [];
  const boundary = (settingsRes.data && settingsRes.data.boundary) || [];

  /* ---------------------------------------------------------
     MAP INIT — MapLibre GL + OpenFreeMap (free, no API key)
  --------------------------------------------------------- */
  // Figure out the real extent of the plan so the camera frames it correctly —
  // a steep tilt over a guessed center was pushing far pins toward the horizon.
  const allCoords = [];
  pins.forEach(p=> allCoords.push([p.lng, p.lat]));
  bridges.forEach(b=> allCoords.push([b.lng, b.lat]));
  boundary.forEach(c=> allCoords.push([c[1], c[0]]));
  let initialCenter = [73.9280, 18.5260];
  if(allCoords.length){
    const lngs = allCoords.map(c=>c[0]), lats = allCoords.map(c=>c[1]);
    initialCenter = [(Math.min(...lngs)+Math.max(...lngs))/2, (Math.min(...lats)+Math.max(...lats))/2];
  }

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://tiles.openfreemap.org/styles/liberty',
    center: initialCenter,
    zoom: 14.5,
    pitch: 0,
    bearing: 0,
    antialias: true
  });
  map.addControl(new maplibregl.NavigationControl({visualizePitch:true}), 'bottom-right');

  map.on('load', ()=>{
    document.getElementById('loading').style.display = 'none';

    // Frame every pin + the boundary while completely flat first — fitBounds
    // miscalculates the required zoom once pitch is already applied, which is
    // what was pushing pins outside the visible plan area. Only after the
    // correct flat fit do we tilt, then zoom out a touch more to compensate
    // for the extra ground the perspective view reveals.
    if(allCoords.length){
      const bounds = allCoords.reduce((b,c)=> b.extend(c), new maplibregl.LngLatBounds(allCoords[0], allCoords[0]));
      map.fitBounds(bounds, {padding:90, duration:0, maxZoom:16});
      const flatZoom = map.getZoom();
      map.jumpTo({ pitch:38, bearing:-17, zoom: Math.max(flatZoom - 0.6, 10) });
    }

    // Find the vector source OpenFreeMap ships (so this keeps working even if they rename it)
    const styleSources = map.getStyle().sources;
    const vectorSourceId = Object.keys(styleSources).find(id => styleSources[id].type === 'vector');

    // 3D building extrusions — the core "flying into a city" effect
    if(vectorSourceId){
      const firstSymbolLayer = map.getStyle().layers.find(l => l.type === 'symbol');
      map.addLayer({
        id: 'mundhwa-3d-buildings',
        source: vectorSourceId,
        'source-layer': 'building',
        type: 'fill-extrusion',
        minzoom: 14,
        paint: {
          'fill-extrusion-color': '#d8cfc0',
          'fill-extrusion-height': ['coalesce', ['get', 'render_height'], 8],
          'fill-extrusion-base': ['coalesce', ['get', 'render_min_height'], 0],
          'fill-extrusion-opacity': 0.85
        }
      }, firstSymbolLayer ? firstSymbolLayer.id : undefined);
    }

    // Boundary outline
    if(boundary.length > 1){
      const ring = boundary.map(c => [c[1], c[0]]);
      ring.push(ring[0]);
      map.addSource('boundary', { type:'geojson', data:{ type:'Feature', geometry:{ type:'Polygon', coordinates:[ring] } } });
      map.addLayer({ id:'boundary-fill', type:'fill', source:'boundary', paint:{ 'fill-color':'#e74c3c', 'fill-opacity':0.04 } });
      map.addLayer({ id:'boundary-line', type:'line', source:'boundary', paint:{ 'line-color':'#e74c3c', 'line-width':2, 'line-dasharray':[3,3] } });
    }

    // Roads / lines, with bridge casing where relevant
    const roadFeatures = roads.filter(r => r.points && r.points.length > 1).map(r=>{
      const meta = infraTypes[r.type] || infraTypes.proposed_road;
      return {
        type:'Feature',
        properties:{ id:r.id, color: r.color || meta.color, weight: r.weight || 5, bridge: isBridgeLike(r.type) ? 1 : 0, dashed: r.type === 'proposed_road' ? 1 : 0, title: r.title || meta.label, notes: r.notes || '' },
        geometry:{ type:'LineString', coordinates: r.points.map(p=>[p[1], p[0]]) }
      };
    });
    map.addSource('roads', { type:'geojson', data:{ type:'FeatureCollection', features: roadFeatures } });
    map.addLayer({
      id:'roads-casing', type:'line', source:'roads',
      filter:['==', ['get','bridge'], 1],
      paint:{ 'line-color':'#ffffff', 'line-width':['+', ['get','weight'], 6], 'line-opacity':0.9 },
      layout:{ 'line-join':'round', 'line-cap':'round' }
    });
    map.addLayer({
      id:'roads-line', type:'line', source:'roads',
      paint:{ 'line-color':['get','color'], 'line-width':['get','weight'], 'line-opacity':0.95,
        'line-dasharray':['case', ['==', ['get','dashed'], 1], ['literal',[2,1.6]], ['literal',[1,0]]] },
      layout:{ 'line-join':'round', 'line-cap':'round' }
    });
    map.on('click', 'roads-line', (e)=>{
      const p = e.features[0].properties;
      new maplibregl.Popup({offset:8}).setLngLat(e.lngLat).setHTML(`<b>${p.title}</b>${p.notes ? '<br>'+p.notes : ''}`).addTo(map);
    });
    map.on('mouseenter', 'roads-line', ()=> map.getCanvas().style.cursor = 'pointer');
    map.on('mouseleave', 'roads-line', ()=> map.getCanvas().style.cursor = '');

    // Infra markers
    bridges.forEach(b=>{
      const meta = infraTypes[b.type] || infraTypes.bridge;
      const sz = infraSizes[b.size] || infraSizes.medium;
      const color = b.color || meta.color;
      const inner = b.icon_image ? `<img src="${b.icon_image}" alt="">` : meta.emoji;
      const el = document.createElement('div');
      el.className = 'infra-pin';
      el.style.width = sz.px+'px'; el.style.height = sz.px+'px'; el.style.background = color; el.style.fontSize = sz.font+'px';
      el.innerHTML = inner;
      const popup = new maplibregl.Popup({offset:sz.px/2+4, closeButton:false, closeOnClick:false}).setHTML(`<b>${meta.emoji} ${b.title || meta.label}</b><br>${meta.label}`);
      const marker = new maplibregl.Marker({element:el, anchor:'bottom'}).setLngLat([b.lng, b.lat]).setPopup(popup).addTo(map);
      // Hover still works for desktop convenience; a tap/click (mobile's
      // equivalent, since there's no hover on touch) toggles it too.
      el.addEventListener('mouseenter', ()=>{ if(!popup.isOpen()) marker.togglePopup(); });
      el.addEventListener('mouseleave', ()=>{ if(popup.isOpen()) marker.togglePopup(); });
      el.addEventListener('click', (evt)=>{ evt.stopPropagation(); marker.togglePopup(); });
    });

    // Project pins
    const pinScale = {small:0.78, medium:1, large:1.35};
    pins.forEach(pin=>{
      const color = statusColor[pin.status] || statusColor.available;
      const head = pin.image ? `<img src="${pin.image}" alt="">` : `<span class="glyph">●</span>`;
      const radar = pin.highlighted ? '<div class="pin-radar"></div>' : '';
      const el = document.createElement('div');
      el.className = 'pin-wrap';
      el.style.color = color;
      el.style.transform = 'scale(' + (pinScale[pin.size] || 1) + ')';
      el.innerHTML = `${radar}<div class="pin-circle" style="background:${color};">${head}</div><div class="pin-tail"></div><div class="pin-ground"></div>`;

      const imgTag = pin.image ? `<img src="${pin.image}" alt="">` : '';
      const shareBtn = `<button class="tc-share" data-share-pin="${pin.id}" type="button">🔗 Share</button>`;
      const html = `<div class="teaser-card">${imgTag}<div class="tc-body">
          <p class="tc-title">${pin.title || 'Untitled project'}</p>
          <span class="tc-status" style="background:${color};">${statusLabel[pin.status] || 'Available'}</span>
          ${pin.type ? `<span class="tc-type">${pin.type}</span>` : ''}
          <div class="tc-meta">${teaserLine(pin)}</div>
          <div class="tc-actions">
            <button data-pin="${pin.id}">View Full Details</button>
            ${shareBtn}
          </div>
        </div></div>`;
      // closeOnClick is off deliberately — we manage open/close ourselves
      // below so behaviour is identical on desktop click and mobile tap
      // (hover doesn't exist on touch, which used to leave the card stuck).
      const popup = new maplibregl.Popup({offset:34, className:'teaser-popup', closeButton:true, closeOnClick:false}).setHTML(html);
      popup.on('open', ()=>{
        const btn = popup._content.querySelector('button[data-pin]');
        if(btn) btn.addEventListener('click', ()=> requestDetails(pin));
        const shareBtnEl = popup._content.querySelector('button[data-share-pin]');
        if(shareBtnEl) shareBtnEl.addEventListener('click', (evt)=>{ evt.stopPropagation(); sharePin(pin); });
      });
      popup.on('close', ()=>{ if(openPopupMarker === marker) openPopupMarker = null; });
      const marker = new maplibregl.Marker({element:el, anchor:'bottom'}).setLngLat([pin.lng, pin.lat]).setPopup(popup).addTo(map);
      // One tap/click opens this card (closing any other open card first);
      // tapping the same pin again, or anywhere else on the map, closes it.
      el.addEventListener('click', (evt)=>{
        evt.stopPropagation();
        if(popup.isOpen()){ closeOpenPopup(); return; }
        openMarkerPopup(marker);
      });
      pinMarkerMap.set(pin.id, {marker, pin});
    });

    // Tapping/clicking anywhere on the map that isn't a pin closes whatever
    // card is currently open — this is the piece that was missing for mobile,
    // where there's no hover event to fall back on.
    map.on('click', ()=> closeOpenPopup());

    // Focus the map on load: a shared pin link (?pin=<id>) takes priority,
    // otherwise the company's own pin (number 1 / Associatte) is focused and highlighted.
    (function focusOnLoad(){
      const urlPinId = new URLSearchParams(window.location.search).get('pin');
      const sharedPin = urlPinId ? pins.find(p => p.id === urlPinId) : null;
      const companyPin = pins.find(p => p.number === 1) ||
        pins.find(p => (p.title || '').toLowerCase().includes('associatte'));
      const targetPin = sharedPin || companyPin;
      if(!targetPin) return;
      const entry = pinMarkerMap.get(targetPin.id);
      if(!entry) return;
      map.flyTo({ center:[targetPin.lng, targetPin.lat], zoom:17, pitch:38, bearing:-17, duration:1200 });
      setTimeout(()=> openMarkerPopup(entry.marker), 1300);
    })();
  });

  const pinMarkerMap = new Map();

  // Tracks which project card is currently open, so only one is ever shown
  // at a time (important when pins sit close together) and a click anywhere
  // else — the map, or another pin — reliably closes it, on desktop or mobile.
  let openPopupMarker = null;
  function closeOpenPopup(){
    if(openPopupMarker && openPopupMarker.getPopup() && openPopupMarker.getPopup().isOpen()){
      openPopupMarker.togglePopup();
    }
    openPopupMarker = null;
  }
  function openMarkerPopup(marker){
    if(openPopupMarker && openPopupMarker !== marker) closeOpenPopup();
    if(!marker.getPopup().isOpen()) marker.togglePopup();
    openPopupMarker = marker;
  }

  /* ---------------------------------------------------------
     LEAD CAPTURE + DETAIL REVEAL (same flow as the 2D map)
  --------------------------------------------------------- */
  const overlayBg = document.getElementById('overlay-bg');
  const leadBox = document.getElementById('lead-box');
  const detailPanel = document.getElementById('detail-panel');
  const leadRole = document.getElementById('lead-role');
  const leadName = document.getElementById('lead-name');
  const leadWhatsapp = document.getElementById('lead-whatsapp');
  const leadWhatsappCode = document.getElementById('lead-whatsapp-code');
  leadWhatsapp.addEventListener('input', ()=>{
    leadWhatsapp.value = leadWhatsapp.value.replace(/\D/g, '').slice(0, 10);
  });
  const leadEmail = document.getElementById('lead-email');
  const leadConsent = document.getElementById('lead-consent');
  const leadError = document.getElementById('lead-error');
  const leadSubmit = document.getElementById('lead-submit');
  const leadCancel = document.getElementById('lead-cancel');
  const leadTitle = document.getElementById('lead-title');

  let pendingPin = null;
  function unlockKey(pinId){ return 'lead_unlocked_' + pinId; }

  function requestDetails(pin){
    if(localStorage.getItem(unlockKey(pin.id))){ showDetails(pin); return; }
    pendingPin = pin;
    leadTitle.textContent = 'See full details — ' + (pin.title || 'this project');
    leadError.textContent = '';
    leadName.value=''; leadWhatsapp.value=''; leadEmail.value=''; leadRole.value='buyer';
    leadWhatsappCode.value = '+91';
    leadConsent.checked = true;
    leadBox.style.display = 'block';
    detailPanel.classList.remove('open');
    overlayBg.classList.add('open');
  }
  leadCancel.addEventListener('click', ()=>{ overlayBg.classList.remove('open'); leadBox.style.display='none'; pendingPin=null; });
  overlayBg.addEventListener('click', (e)=>{ if(e.target === overlayBg){ overlayBg.classList.remove('open'); leadBox.style.display='none'; pendingPin=null; } });

  leadSubmit.addEventListener('click', async ()=>{
    const name = leadName.value.trim(), whatsappDigits = leadWhatsapp.value.trim(), email = leadEmail.value.trim(), role = leadRole.value;
    if(!name || !whatsappDigits || !email){ leadError.textContent = 'Please fill in all fields.'; return; }
    if(!/^\d{10}$/.test(whatsappDigits)){ leadError.textContent = 'WhatsApp number must be exactly 10 digits.'; return; }
    const whatsapp = leadWhatsappCode.value + ' ' + whatsappDigits;
    if(!/^\S+@\S+\.\S+$/.test(email)){ leadError.textContent = 'Please enter a valid email.'; return; }
    if(!leadConsent.checked){ leadError.textContent = 'Please provide consent to continue.'; return; }
    leadSubmit.disabled = true; leadSubmit.textContent = 'Submitting…';
    const { error } = await sb.from('leads').insert({ pin_id: pendingPin.id, role, name, whatsapp, email, consent: leadConsent.checked });
    leadSubmit.disabled = false; leadSubmit.textContent = 'View Details';
    if(error){ leadError.textContent = 'Something went wrong — please try again.'; return; }
    localStorage.setItem(unlockKey(pendingPin.id), '1');
    leadBox.style.display = 'none';
    showDetails(pendingPin);
  });

  function showDetails(pin){
    const color = statusColor[pin.status] || statusColor.available;
    const img = document.getElementById('detail-img');
    if(pin.image){ img.src = pin.image; img.style.display = 'block'; } else { img.style.display = 'none'; }
    let rows = '';
    if(pin.status === 'sold'){
      rows = `<div class="detail-row"><label>Status</label><div class="value">This project has been sold out.</div></div>`;
    } else {
      if(pin.price) rows += `<div class="detail-row"><label>Price</label><div class="value price">${pin.price}</div></div>`;
      if(pin.status === 'construction' || pin.status === 'upcoming'){
        if(pin.configuration) rows += `<div class="detail-row"><label>Configuration</label><div class="value">${pin.configuration}</div></div>`;
        if(pin.sqft) rows += `<div class="detail-row"><label>Sq Ft</label><div class="value">${pin.sqft}</div></div>`;
      }
      if(pin.status === 'construction' && pin.possession_timeline) rows += `<div class="detail-row"><label>Possession Timeline</label><div class="value">${pin.possession_timeline}</div></div>`;
      if(pin.status === 'upcoming' && pin.launch_date) rows += `<div class="detail-row"><label>Approximate Launch Date</label><div class="value">${pin.launch_date}</div></div>`;
      if(pin.status === 'available' && pin.whats_available) rows += `<div class="detail-row"><label>What's Available</label><div class="value">${pin.whats_available}</div></div>`;
    }
    if(pin.description) rows += `<div class="detail-row"><label>Description</label><div class="value">${pin.description}</div></div>`;
    const detailShareBtn = `<button class="detail-share" type="button" id="detail-share-btn">🔗 Share this project</button>`;
    document.getElementById('detail-body').innerHTML = `
      <h2>${pin.title || 'Untitled project'}</h2>
      <span class="status-badge" style="background:${color};">${statusLabel[pin.status] || 'Available'}</span>
      ${pin.type ? `<div class="detail-row"><label>Type</label><div class="value">${pin.type}</div></div>` : ''}
      ${rows}
      ${detailShareBtn}
    `;
    const shareEl = document.getElementById('detail-share-btn');
    if(shareEl) shareEl.addEventListener('click', ()=> sharePin(pin));
    overlayBg.classList.add('open');
    detailPanel.classList.add('open');
  }
  document.getElementById('detail-close').addEventListener('click', ()=>{
    detailPanel.classList.remove('open'); overlayBg.classList.remove('open');
  });

  /* ---------------------------------------------------------
     SEARCH — flies the camera to the matching project
  --------------------------------------------------------- */
  document.getElementById('search-input').addEventListener('input', (e)=>{
    const q = e.target.value.trim().toLowerCase();
    if(!q) return;
    const match = pins.find(p => (p.title||'').toLowerCase().includes(q));
    if(match){
      map.flyTo({ center:[match.lng, match.lat], zoom:16.5, pitch:42, essential:true });
      const entry = pinMarkerMap.get(match.id);
      if(entry) openMarkerPopup(entry.marker);
    }
  });

  // ---------- View-source deterrent: TEMPORARILY DISABLED ----------
